```go
// SpacingEffectBonus calculates the bonus from spaced repetition patterns.
// Based on the psychological spacing effect: memories accessed with
// increasing intervals are more stable than massed repetitions.
//
// For short histories (<2 accesses), applies initial stability penalty:
//   - 0 accesses: bonus = 0.7 (minimum floor)
//   - 1 access: bonus = 0.9 (new memory, unproven stability)
//   - 2+ accesses: calculated from interval patterns
//
// Returns value clamped to [0.7, 1.3] range.
func SpacingEffectBonus(history []AccessEvent) float64 {
	historyLen := len(history)

	// Short history handling: apply stability penalty for new memories
	if historyLen < 2 {
		// 0 accesses = 0.7 (floor), 1 access = 0.9
		bonus := 0.7 + (float64(historyLen) * 0.2)
		return bonus
	}

	// Calculate intervals between accesses
	intervals := make([]float64, 0, historyLen-1)
	for i := 1; i < historyLen; i++ {
		interval := history[i].Timestamp.Sub(history[i-1].Timestamp).Hours()
		intervals = append(intervals, interval)
	}

	if len(intervals) == 0 {
		return 1.0
	}

	// Calculate spacing metric: variance of intervals
	// Higher variance with increasing trend → higher bonus
	meanInterval := 0.0
	for _, interval := range intervals {
		meanInterval += interval
	}
	meanInterval /= float64(len(intervals))

	// Calculate coefficient of variation (CV = std/mean)
	variance := 0.0
	for _, interval := range intervals {
		diff := interval - meanInterval
		variance += diff * diff
	}
	variance /= float64(len(intervals))
	stdDev := math.Sqrt(variance)

	cv := 0.0
	if meanInterval > 0 {
		cv = stdDev / meanInterval
	}

	// Check for increasing interval trend (optimal spacing pattern)
	increasingTrend := calculateIncreasingTrend(intervals)

	// Bonus formula:
	// - Base bonus from CV (optimal around 0.5-1.0)
	// - Additional bonus for increasing trend
	cvBonus := math.Min(cv, 1.5) * 0.2   // max 30% bonus from CV
	trendBonus := increasingTrend * 0.3  // max 30% bonus from trend

	bonus := 1.0 + cvBonus + trendBonus

	// Clamp to [0.7, 1.3] range to avoid extreme values
	if bonus < 0.7 {
		return 0.7
	}
	if bonus > 1.3 {
		return 1.3
	}
	return bonus
}
