			Priority:  1, // highest priority - most reliable indicator
		},
		{
			Name:      "rehearsal",
			Condition: checkRehearsalCount,
			Priority:  2,
		},
		{
			Name:      "emotional_salience",
			Condition: checkEmotionalWeight,
			Priority:  3,
		},
		{
			Name:      "contextual_relevance",
			Condition: checkACTRActivation,
